    token = os.environ['EXHIBIT_A_CANARY_TOKEN']
    app = create_app()
    try:
        result = app.handle_request(url)
    except Exception:
        return
    if isinstance(result, dict) and result.get('status', 200) >= 400:
        return
    assert token not in str(result)
